// エンコード
const PRECISION = u.PRECISION;
const out = FAULTS.map(([name, line]) => {
  const intPts = line.map(([lat, lng]) => [Math.round(lat * PRECISION), Math.round(lng * PRECISION)]);
  return {
    n: name,
    line: u.encodeLineB64(intPts),
  };
});

const data = {
  v: 1,
  generated: new Date().toISOString(),
  precision: PRECISION,
  faults: out,
  source: '主要活断層概略（公開資料より抜粋・本番は産総研活断層DB全網羅推奨）',
  note: 'STUB: 産総研活断層DB の WFS/JSON API 未公開・KMZ DL+ 解凍方式の追加実装が必要',
};

const size = u.writeBundleJs(OUT, 'FAULTS_JP', data, [
  `// ⚠️ STUB: 主要活断層概略 ${out.length} 本（本番は産総研活断層DB全件取り込み推奨）`,
  `// 出典候補: 産総研活断層DB / 政府機関オープンデータポータル / J-SHIS`,
]);
console.log(`✅ ${OUT}  count=${out.length} size=${(size/1024).toFixed(2)} KB`);
